import{_ as e,o as s,c as n,a0 as t}from"./chunks/framework.BpJS36ta.js";const u=JSON.parse('{"title":"Import","description":"","frontmatter":{},"headers":[],"relativePath":"syntax/import.md","filePath":"syntax/import.md"}'),i={name:"syntax/import.md"};function p(o,a,r,d,l,c){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h1><p>Import kode dari file lain ke dalam scope saat ini. Import statements harus berada di bagian atas file.</p><h2 id="bentuk-kanonik" tabindex="-1">Bentuk kanonik <a class="header-anchor" href="#bentuk-kanonik" aria-label="Permalink to &quot;Bentuk kanonik&quot;">​</a></h2><p>Hanya ada <strong>dua bentuk import</strong> yang jadi standar bahasa, ditambah navigasi pohon package:</p><h3 id="_1-semua-member-—-import-as-x-from-x" tabindex="-1">1. Semua member — <code>import * as x from ./X</code> <a class="header-anchor" href="#_1-semua-member-—-import-as-x-from-x" aria-label="Permalink to &quot;1. Semua member — \`import * as x from ./X\`&quot;">​</a></h3><p>Ambil semua yang ada di X, simpan sebagai namespace <code>x</code>:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import * as x from ./X</span></span>
<span class="line"><span></span></span>
<span class="line"><span>x.create()</span></span>
<span class="line"><span>x.update()</span></span></code></pre></div><p>Tanpa alias, seluruh member di-flatten ke scope saat ini:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import * from ./X</span></span>
<span class="line"><span></span></span>
<span class="line"><span>create()</span></span>
<span class="line"><span>update()</span></span></code></pre></div><h3 id="_2-selective-—-import-x-y-from-x" tabindex="-1">2. Selective — <code>import x, y from ./X</code> <a class="header-anchor" href="#_2-selective-—-import-x-y-from-x" aria-label="Permalink to &quot;2. Selective — \`import x, y from ./X\`&quot;">​</a></h3><p>Ambil hanya <code>x</code> dan <code>y</code> dari X:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import create, update from ./modules.a</span></span>
<span class="line"><span></span></span>
<span class="line"><span>create()</span></span>
<span class="line"><span>update()</span></span></code></pre></div><p>Nama binding mengikuti nama member — <code>import info from ./os</code> memanggil <code>info()</code> langsung di top-level.</p><blockquote><p>Prinsip desain: import dan export memakai bentuk yang <strong>setara</strong> — <code>*</code> (semua) dan selective (sebagian). Member chain (<code>x.y</code>), wildcard member (<code>x.*</code>), entry alias (<code>x as y</code>), source alias (<code>from X as m</code>), dan bare import (<code>import X</code>) bukan bagian dari grammar.</p></blockquote><h2 id="stdlib" tabindex="-1">Stdlib <a class="header-anchor" href="#stdlib" aria-label="Permalink to &quot;Stdlib&quot;">​</a></h2><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import os from rupa               // module os → os.info()</span></span>
<span class="line"><span>import db, math from rupa         // beberapa module sekaligus</span></span>
<span class="line"><span>import info from rupa.os          // selective: fungsi info dari module os</span></span></code></pre></div><h2 id="navigasi-pohon-package" tabindex="-1">Navigasi pohon package <a class="header-anchor" href="#navigasi-pohon-package" aria-label="Permalink to &quot;Navigasi pohon package&quot;">​</a></h2><p>Import dengan dotted path <strong>bukan akses langsung ke file</strong> — resolusinya berurutan dengan urutan tetap:</p><ol><li><strong>Z-self menang</strong> — bila <code>pkg/y/z.rp</code> ada <strong>dan punya statement export</strong> (<code>export *</code>, <code>export x</code>, atau <code>namespace</code>), path adalah referensi langsung ke file leaf itu. Leaf polos tanpa export tidak dihitung.</li><li><strong>Tree navigation</strong> — bila tidak, <code>pkg/y/index.rp</code> wajib ada: masuk cabang <code>y</code>, ambil member <code>z</code> dari export index cabangnya (&quot;apakah ada sub module yang di-export?&quot;).</li><li><strong>Tidak keduanya</strong> → <code>ImportError</code> — tidak ada fallback diam-diam.</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rpx_engine/</span></span>
<span class="line"><span>├── index.rp            export view from ./view</span></span>
<span class="line"><span>└── view/</span></span>
<span class="line"><span>    ├── index.rp        export resources from ./resources -&gt; { load: private }</span></span>
<span class="line"><span>    └── resources.rp    leaf — tanpa export → hanya via index cabang</span></span></code></pre></div><p>Semua bentuk ini sah dan setara menavigasi pohon yang sama:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import v from ./rpx_engine                      // root → v.view.resources</span></span>
<span class="line"><span>import view from ./rpx_engine.view              // masuk sub-package sebagai root</span></span>
<span class="line"><span>import resources from ./rpx_engine.view.resources  // redirect ke view/index.rp</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(v.view.resources.id)      // ✅</span></span>
<span class="line"><span>print(view.resources.id)        // ✅ sama pohonnya</span></span>
<span class="line"><span>print(resources.id)             // ✅ member dari index cabang</span></span></code></pre></div><p>Dotted path yang melompati pohon ditolak:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import z from ./rpx_engine.z    // ❌ ImportError — tidak ada cabang z</span></span></code></pre></div><p>Leaf yang mengekspor dirinya terjangkau langsung:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// view/tools.rp — punya \`export *\`</span></span>
<span class="line"><span>import tools from ./rpx_engine.view.tools   // ✅ Z-self: akses langsung</span></span></code></pre></div><p>Catatan:</p><ul><li><strong>Module dieksekusi sekali</strong> per run, berapa kali pun di-import atau di-export ulang antar index.</li><li><strong>Binding import tidak bocor</strong> — <code>import fs, os from rupa</code> di dalam leaf adalah konsumsi internal: <code>fs</code>/<code>os</code> tidak muncul di object yang dilihat consumer. Yang terekspos hanya yang didefinisikan file tersebut.</li></ul><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// view/resources.rp</span></span>
<span class="line"><span>import fs, os from rupa         // konsumsi internal</span></span>
<span class="line"><span>const id = &quot;res&quot;</span></span></code></pre></div><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import resources from ./rpx_engine.view.resources</span></span>
<span class="line"><span>print(resources.fs)             // undefined — fs bukan milik resources</span></span>
<span class="line"><span>print(resources.id)             // &quot;res&quot;</span></span></code></pre></div><h2 id="ringkasan" tabindex="-1">Ringkasan <a class="header-anchor" href="#ringkasan" aria-label="Permalink to &quot;Ringkasan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Syntax</th><th>Hasil</th></tr></thead><tbody><tr><td><code>import * as x from ./X</code></td><td><strong>Kanonik</strong> — semua member X sebagai namespace <code>x</code></td></tr><tr><td><code>import * from ./X</code></td><td>Semua member X di-flatten ke scope</td></tr><tr><td><code>import x, y from ./X</code></td><td><strong>Kanonik</strong> — selective: hanya <code>x</code> dan <code>y</code></td></tr><tr><td><code>import X from rupa</code></td><td>Module X dari stdlib</td></tr><tr><td><code>import X, Y from rupa</code></td><td>Beberapa module stdlib</td></tr><tr><td><code>import X from rupa.Y</code></td><td>Selective dari module Y</td></tr><tr><td><code>import X from ./pkg.a.b</code></td><td>Navigasi pohon package — member <code>b</code> dari index cabang <code>a</code></td></tr></tbody></table>`,32)])])}const g=e(i,[["render",p]]);export{u as __pageData,g as default};
